                    { id: 'q1_c', label: 'Python', value: 'python' },
                    { id: 'q1_d', label: 'Rust', value: 'rust' }
                ]
            },
            {
                id: 'q2',
                title: '2. Which of these languages or tools are primarily used for frontend web development?',
                options: [
                    { id: 'q2_a', label: 'C#', value: 'csharp' },
                    { id: 'q2_b', label: 'HTML', value: 'html' },
                    { id: 'q2_c', label: 'TypeScript', value: 'typescript' },
                    { id: 'q2_d', label: 'CSS', value: 'css' }
                ]
            },
            {
                id: 'q3',
                title: '3. Which of the following languages are widely known for systems programming?',
                options: [
                    { id: 'q3_a', label: 'C', value: 'c' },
